import{_ as i,o as a,c as l,ae as o}from"./chunks/framework.qNV68s4p.js";const p=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1776335312000}'),r={name:"zh/guide/architecture.md"};function t(n,e,d,c,h,u){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>SweetEditor 的核心设计是“原生编辑器内核 + Kotlin/Compose 包装层”的严格分层。</p><h2 id="顶层结构" tabindex="-1">顶层结构 <a class="header-anchor" href="#顶层结构" aria-label="Permalink to &quot;顶层结构&quot;">​</a></h2><ul><li><code>editor-core</code>: 原生编辑器内核</li><li><code>editor-compose</code>: Kotlin Multiplatform 包装层与 Compose UI 集成</li><li><code>example</code>: 参考应用</li><li><code>platform-demo</code>: 平台专用 demo 与实验代码</li></ul><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h2><p>它<strong>不是</strong> <code>BasicTextField</code> 的增强版，而是一套专用编辑器架构：</p><ul><li>native kernel 负责编辑语义和核心算法</li><li>Kotlin 层负责状态包装、协议解码和平台桥接</li><li>Compose 层消费 render model，而不是重新推导编辑器状态</li></ul><h2 id="各层职责" tabindex="-1">各层职责 <a class="header-anchor" href="#各层职责" aria-label="Permalink to &quot;各层职责&quot;">​</a></h2><h2 id="native-core" tabindex="-1">Native Core <a class="header-anchor" href="#native-core" aria-label="Permalink to &quot;Native Core&quot;">​</a></h2><p>原生 core 负责：</p><ul><li>文档模型</li><li>编辑算法</li><li>光标与选区语义</li><li>render model 生成</li><li>折叠、括号匹配、高亮和诊断等核心能力</li><li>对 Kotlin 暴露的 C API</li></ul><h2 id="kotlin-wrapper" tabindex="-1">Kotlin Wrapper <a class="header-anchor" href="#kotlin-wrapper" aria-label="Permalink to &quot;Kotlin Wrapper&quot;">​</a></h2><p>Kotlin Multiplatform 层负责：</p><ul><li>安全调用 native bridge</li><li>解析二进制协议</li><li>管理 native-backed document 生命周期</li><li>暴露控制器、Provider、事件总线等公共 API</li><li>按 source set 隔离平台差异</li></ul><h2 id="compose-ui" tabindex="-1">Compose UI <a class="header-anchor" href="#compose-ui" aria-label="Permalink to &quot;Compose UI&quot;">​</a></h2><p>Compose 层负责：</p><ul><li>渲染编辑器表面</li><li>指针、键盘、IME 事件集成</li><li>completion popup、inline suggestion action bar 等 UI</li><li>文本测量和主题应用</li></ul><h2 id="为什么不建议在-kotlin-里重写-core-算法" tabindex="-1">为什么不建议在 Kotlin 里重写 Core 算法 <a class="header-anchor" href="#为什么不建议在-kotlin-里重写-core-算法" aria-label="Permalink to &quot;为什么不建议在 Kotlin 里重写 Core 算法&quot;">​</a></h2><ul><li>容易与原生语义分叉</li><li>会破坏 render model 作为单一事实来源的设计</li><li>难以保证跨平台一致性</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./getting-started">入门</a></li><li>英文 <a href="./../../guide/theme-appearance">Theme / Appearance</a></li><li>英文 <a href="./../../guide/api-overview">API Overview</a></li></ul>',21)])])}const m=i(r,[["render",t]]);export{p as __pageData,m as default};
